import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`quickbooks-health-check`,hasInputUrl:!1,heroTitle:`Audit your QuickBooks financials`,heroSubtitle:`Perplexity Computer audits your chart of accounts, flags reconciliation gaps, and delivers a fix-it report — automatically.`,heroOverlaySteps:[`Connecting to your QuickBooks account and pulling financial data`,`Auditing your chart of accounts, reconciliations, and open transactions`,`Flagging misclassifications, duplicates, and reconciliation gaps`,`Health score, error log, and prioritized fix-it plan — ready to review`],generatingSteps:[`Analyzing your QuickBooks account structure, transactions, and reconciliation status`,`Designing an agent to audit your chart of accounts and flag classification errors`,`Configuring duplicate detection, unreconciled transaction scanning, and balance verification`,`Setting up your health score dashboard with prioritized cleanup actions`],featureSectionTitle:`From messy books to clean financials`,featureCardTitles:[`Connects to your accounting stack`,`Outputs you can fix today`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`QuickBooks, Google Sheets, Xero, Slack, Google Drive — Computer plugs into your tools so audit findings flow straight into your cleanup workflow.`,`Overall health score. Misclassified transaction log. Unreconciled account list. Duplicate entry report. A prioritized fix-it plan with step-by-step instructions.`],capabilitySectionTitle:`Your bookkeeper, on autopilot`,capabilitySectionSubtitle:`Start your health check, step away, come back to a clean-books action plan.`,capabilityCards:[{title:`Chart of Accounts Audit`,description:`Computer can review every account in your chart — flagging inactive accounts, misclassifications, and redundant categories that bloat your books.`},{title:`Reconciliation Check`,description:`Computer can scan every bank and credit card account for unreconciled transactions — and surface discrepancies between your books and your statements.`},{title:`Duplicate Detection`,description:`Computer can identify duplicate entries, split transactions, and double-posted invoices — catching the errors that silently distort your financials.`},{title:`Connect Your Tools`,description:`Computer can pull data from QuickBooks, Google Sheets, Xero, Google Drive, and Slack — build workflows across your entire accounting stack.`},{title:`Remember & Learn`,description:`Computer can remember your chart of accounts, past health scores, and recurring issues — so every audit tracks progress and catches regressions.`},{title:`Monitor & Alert`,description:`Computer can run monthly health checks automatically and alert you when reconciliation gaps widen or new classification errors appear.`}]});export{t as default};
